import {presentCombatTurn} from './combat-animation.js';
export function createRemoteCombat(env){
 const current=()=>env.getCombat(),later=(b,fn,ms)=>setTimeout(()=>{if(current()===b)fn();},ms);
 function render(b){env.modal(env.presentation.arena(b),'combat-modal immersive-combat');}
 function adopt(b,m){b.match=m;b.ticket={player:m.player,opponent:m.opponent,rules:m.rules,reward:m.reward,loss:m.loss};b.energy=m.energy;b.round=m.round;b.yourTurn=m.yourTurn;b.turnDeadline=m.turnDeadline;}
 function start(m){const b={remote:true,kind:m.kind,scene:m.scene,busy:false,playerHP:m.playerHP,enemyHP:m.enemyHP,energy:m.energy,round:m.round,playerRow:0,enemyRow:0,action:'',log:m.yourTurn?'É seu turno. Escolha seu movimento.':'Aguardando o movimento do adversário.'};adopt(b,m);env.setCombat(b);env.audio.setScene('combat');env.audio.play('start');render(b);poll(b);}
 function poll(b){if(b.pollScheduled)return;b.pollScheduled=true;later(b,async()=>{b.pollScheduled=false;if(b.busy){poll(b);return;}try{const response=await env.action('arena_poll_match',{match_id:b.match.id}),m=response.match;if(m.version!==b.match.version){if(m.lastMove?.actorId!==env.getState().profile.id&&m.playerHP!==b.playerHP){animateEnemy(b,m);return;}adopt(b,m);b.playerHP=m.playerHP;b.enemyHP=m.enemyHP;if(m.status==='completed'){finish(b);return;}b.log=b.yourTurn?'É seu turno.':'Aguardando o adversário.';render(b);}}catch(e){b.log=e.message;render(b);}poll(b);},1400);}
 function animateEnemy(b,m){const move=m.lastMove?.move||'attack',duration=m.rules.actionMs,damage=b.playerHP-m.playerHP;b.busy=true;b.action='enemy-attack';b.moveKind=move;b.enemyRow=move==='special'?5:move==='shield'?4:1;b.motion='windup';b.log='O adversário prepara seu movimento…';env.audio.play(move==='special'?'charge':'servo',b.ticket.opponent.def);render(b);
 later(b,()=>{b.motion='strike';env.audio.play(move,b.ticket.opponent.def);render(b);},duration*.28);
 later(b,()=>{b.motion='impact';b.previousPlayerHP=b.playerHP;b.playerHP=m.playerHP;b.playerDamage=damage;b.playerRow=2;b.log='Ataque recebido: '+damage+' de dano.';env.audio.play('hit',b.ticket.player);render(b);},duration*.52);
 later(b,()=>{b.busy=false;b.action='';b.motion='idle';b.playerRow=b.enemyRow=0;adopt(b,m);b.enemyHP=m.enemyHP;if(m.status==='completed')finish(b);else{b.log='É seu turno. Escolha seu movimento.';render(b);poll(b);}},duration);
 }
 async function move(kind){const b=current();if(!b?.remote||b.busy||!b.yourTurn)return;b.busy=true;render(b);try{const {match:m}=await env.action(b.kind==='guild'?'guild_move':'arena_move',{match_id:b.match.id,expected_version:b.match.version,move:kind});const result={damage:Math.max(0,b.enemyHP-m.enemyHP),enemyHP:m.enemyHP,retaliation:Math.max(0,b.playerHP-m.playerHP),playerHP:m.playerHP,defeated:m.enemyHP<=0,noRetaliation:!m.opponent.isBot};adopt(b,m);const completed=()=>{b.playerHP=m.playerHP;b.enemyHP=m.enemyHP;if(m.status==='completed')finish(b);else{b.log=m.yourTurn?'É seu turno.':'Movimento enviado. Aguardando o adversário.';render(b);poll(b);}};presentCombatTurn({battle:b,kind,result,render,later,audio:env.audio,onDefeated:completed,onComplete:completed});}catch(e){b.busy=false;env.toast(e.message,true);render(b);poll(b);}}
 function finish(b){if(current()!==b)return;const m=b.match;env.setCombat(null);env.render();env.audio.play(m.win?'victory':'lose');env.modal(`<div class="battle-result ${m.win?'win':'lose'}">${env.sprite(m.player,'result-sprite',m.win?3:2)}<span class="eyebrow">${m.kind==='guild'?'DUELO DE GUILDA':'ARENA'} ENCERRADO</span><h2 id="modal-title">${m.win?'Vitória!':'Prepare sua próxima evolução.'}</h2><div class="result-reward">${env.coin('RC')}${m.win?'+':'−'}${m.win?m.reward:m.loss} RC</div><p>Resultado e carteira confirmados pelo servidor.</p>${env.button('Continuar','close','','primary wide')}</div>`);}
 async function exit(){const b=current();if(!b?.remote)return;try{const {match:m}=await env.action('arena_finish',{match_id:b.match.id,forfeit:true});adopt(b,m);finish(b);}catch(e){env.toast(e.message,true);}}
 return {start,move,exit};
}
